// HasAttempts applies the HasEdge predicate on the "attempts" edge.
func HasAttempts() predicate.RelocationItem {
	return predicate.RelocationItem(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, AttemptsTable, AttemptsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasAttemptsWith applies the HasEdge predicate on the "attempts" edge with a given conditions (other predicates).
func HasAttemptsWith(preds ...predicate.RelocationAttempt) predicate.RelocationItem {
	return predicate.RelocationItem(func(s *sql.Selector) {
		step := newAttemptsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.RelocationItem) predicate.RelocationItem {
	return predicate.RelocationItem(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.RelocationItem) predicate.RelocationItem {
	return predicate.RelocationItem(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.RelocationItem) predicate.RelocationItem {
	return predicate.RelocationItem(sql.NotPredicates(p))
}
